const grpc = require('@grpc/grpc-js');
const { orderEventEmitter } = require('../events');
const { verifyClientSession } = require('../session');
const { db } = require('../db');

function liveOrderTrackingStream(call) {
  const session = verifyClientSession(call.metadata);
  if (!session) return call.destroy(new Error('Session invalid'));

  call.on('data', async (request) => {
    const { orderId } = request;
    const check = await db.query(
      'SELECT id FROM orders WHERE id = $1 AND (customer_id = $2 OR courier_id = $2)',
      [orderId, session.userId]
    );
    if (check.rowCount === 0) return;

    const onUpdate = (event) => {
      call.write({
        orderId: event.orderId,
        courierLatitude: event.lat,
        courierLongitude: event.lng,
        customerPhone: event.customerPhone
      });
    };
    orderEventEmitter.on(`order:${orderId}`, onUpdate);
    call.on('close', () => orderEventEmitter.off(`order:${orderId}`, onUpdate));
  });
}
